class Solution {
public:
    int countStaircase(vector<int>& nums) {
        int n = (int)nums.size();
        // maximum possible distinct values in a staircase
        int K = 0;
        while (1LL * (K + 1) * (K + 2) / 2 <= n) ++K;

        long long ans = 0;
        for (int L = 0; L < n; ++L) {
            unordered_map<int, pair<int,int>> mp; // value -> (rank, cnt)
            mp.reserve(K * 2);
            int distinct = 0;
            int bad = 0;               // number of values whose cnt != rank
            for (int R = L; R < n; ++R) {
                int v = nums[R];
                auto it = mp.find(v);
                if (it == mp.end()) {
                    ++distinct;
                    if (distinct > K) break;          // too many distinct values
                    int rank = distinct;
                    int cnt = 1;
                    if (cnt != rank) ++bad;            // mismatched right away
                    mp.emplace(v, make_pair(rank, cnt));
                } else {
                    int rank = it->second.first;
                    int cnt = it->second.second;
                    // adjust bad before changing cnt
                    if (cnt == rank) ++bad;            // will become mismatched
                    else if (cnt == rank - 1) --bad;   // will become matched
                    ++cnt;
                    if (cnt > rank) break;             // impossible to fix later
                    it->second.second = cnt;
                }
                if (bad == 0) ++ans;                    // current window is a staircase
            }
        }
        return (int)ans;
    }
};

