import java.util.HashMap;
import java.util.Map;

class Solution {
    public int countStaircase(int[] nums) {
        int n = nums.length;
        // maximum possible distinct values in a staircase
        int K = 0;
        while (1L * (K + 1) * (K + 2) / 2 <= n) ++K;

        long ans = 0;
        for (int L = 0; L < n; ++L) {
            Map<Integer, int[]> mp = new HashMap<>(); // value -> [rank, cnt]
            int distinct = 0;
            int bad = 0;               // number of values whose cnt != rank
            for (int R = L; R < n; ++R) {
                int v = nums[R];
                int[] info = mp.get(v);
                if (info == null) {
                    ++distinct;
                    if (distinct > K) break;          // too many distinct values
                    int rank = distinct;
                    int cnt = 1;
                    if (cnt != rank) ++bad;            // mismatched right away
                    mp.put(v, new int[]{rank, cnt});
                } else {
                    int rank = info[0];
                    int cnt = info[1];
                    // adjust bad before changing cnt
                    if (cnt == rank) ++bad;            // will become mismatched
                    else if (cnt == rank - 1) --bad;   // will become matched
                    ++cnt;
                    if (cnt > rank) break;             // impossible to fix later
                    info[1] = cnt;
                }
                if (bad == 0) ++ans;                    // current window is a staircase
            }
        }
        return (int) ans;
    }
}

