class Solution:
    def countStaircase(self, nums: list[int]) -> int:
        n = len(nums)
        # maximum possible distinct values in a staircase
        K = 0
        while (K + 1) * (K + 2) // 2 <= n:
            K += 1

        ans = 0
        for L in range(n):
            mp = {}  # value -> [rank, cnt]
            distinct = 0
            bad = 0  # number of values whose cnt != rank
            for R in range(L, n):
                v = nums[R]
                if v not in mp:
                    distinct += 1
                    if distinct > K:
                        break  # too many distinct values
                    rank = distinct
                    cnt = 1
                    if cnt != rank:
                        bad += 1  # mismatched right away
                    mp[v] = [rank, cnt]
                else:
                    rank, cnt = mp[v]
                    # adjust bad before changing cnt
                    if cnt == rank:
                        bad += 1  # will become mismatched
                    elif cnt == rank - 1:
                        bad -= 1  # will become matched
                    cnt += 1
                    if cnt > rank:
                        break  # impossible to fix later
                    mp[v][1] = cnt
                if bad == 0:
                    ans += 1
        return ans

