/**
 * @param {number[]} nums
 * @return {number}
 */
var countStaircase = function(nums) {
    const n = nums.length;
    // maximum possible distinct values in a staircase
    let K = 0;
    while ((K + 1) * (K + 2) / 2 <= n) ++K;

    let ans = 0;
    for (let L = 0; L < n; ++L) {
        const mp = new Map(); // value -> [rank, cnt]
        let distinct = 0;
        let bad = 0; // number of values whose cnt != rank
        for (let R = L; R < n; ++R) {
            const v = nums[R];
            if (!mp.has(v)) {
                ++distinct;
                if (distinct > K) break; // too many distinct values
                const rank = distinct;
                const cnt = 1;
                if (cnt !== rank) ++bad; // mismatched right away
                mp.set(v, [rank, cnt]);
            } else {
                const entry = mp.get(v);
                const rank = entry[0];
                let cnt = entry[1];
                // adjust bad before changing cnt
                if (cnt === rank) ++bad;          // will become mismatched
                else if (cnt === rank - 1) --bad; // will become matched
                ++cnt;
                if (cnt > rank) break; // impossible to fix later
                entry[1] = cnt;
                mp.set(v, entry);
            }
            if (bad === 0) ++ans; // current window is a staircase
        }
    }
    return ans;
};
